import json

def transform_final3(grid):
    if not grid or not grid[0]:
        return []

    ph, pw = len(grid), len(grid[0])
    output = [[v for v in row] for row in grid]  # Copy input

    targets = []
    for r in range(ph):
        for c in range(pw):
            if grid[r][c] > 1:
                targets.append((r, c, grid[r][c]))

    for r, c, val in targets:
        h = max(1, 5 - (c + 3) // 4)
        top_row = r - h

        for i in range(h):
            out_row = top_row + i
            if 0 <= out_row < ph:
                if out_row == top_row:
                    output[out_row][c] = val
                else:
                    output[out_row][c] = 1

    return output

